def fitstat(a, b):
    a = a.reshape(-1); b = b.reshape(-1)
    sl = (a*b).sum()/(b*b).sum(); r2 = 1 - ((a - sl*b)**2).sum()/((a - a.mean())**2).sum()
    return round(sl.item(),3), round(r2.item(),3)
