import json, numpy as np, pandas as pd, inspect, torch
def cv(x):
    try:
        return int(x)
    except Exception:
        return str(x)
def rng(a):
    try:
        a = sorted(int(x) for x in a)
    except Exception:
        return None
    r = []; s0 = p = a[0]
    for x in a[1:]:
        if x == p + 1:
            p = x
            continue
        r.append(f"{s0}-{p}" if p > s0 else f"{s0}")
        s0 = p = x
    r.append(f"{s0}-{p}" if p > s0 else f"{s0}")
    return r
